// NOTE: Badge wrapper for navbar links that display metadata (version, blog posts, etc.)
'use client';

import Link from 'next/link';
import { Badge } from '@/components/ui/badge';
import { cn } from '@/lib/utils';
import { motion } from 'motion/react';
import { EASE } from '@/lib/animation-config';

interface NavbarBadgeLinkProps {
  href: string;
  label: string;
  icon?: React.ReactNode;
  metadata: string; // version number or blog post title
  active?: boolean;
  className?: string;
}

/**
 * NavbarBadgeLink Component
 *
 * A specialized link component that displays as a pill badge with metadata.
 * Used in the navbar for Changelog (with version) and Blog (with latest post).
 *
 * Features:
 * - Combines shadcn Badge with Next.js Link
 * - Displays label | metadata with pipe separator
 * - Smooth hover animations matching navbar style
 * - Active state highlighting
 * - Respects navbar variant styling through className prop
 *
 * @example
 * <NavbarBadgeLink
 *   href="/changelog"
 *   label="Changelog"
 *   metadata="v0.1.0"
 *   active={pathname === '/changelog'}
 * />
 */
export function NavbarBadgeLink({
  href,
  label,
  metadata,
  icon,
  active = false,
  className,
}: NavbarBadgeLinkProps) {
  return (
    <Link href={href}>
      <motion.div
        whileHover={{
          scale: 1.05,
          transition: {
            duration: 0.2,
            ease: EASE.expOut,
          },
        }}
        whileTap={{ scale: 0.97 }}
      >
        <Badge
          variant={'outline'}
          className={cn(
            'h-9 cursor-pointer gap-2 px-2 py-2 text-lg font-semibold transition-all',
            active && 'bg-accent text-accent-foreground',
            className
          )}
        >
          <span className="rounded-4xl bg-[#222] px-2 text-white">{label}</span>
          <span className="dark:text-foreground font-normal text-black">
            {metadata}
          </span>
          {icon && (
            <span className="dark:text-foreground flex items-center text-black">
              {icon}
            </span>
          )}
        </Badge>
      </motion.div>
    </Link>
  );
}
